(window.VitanovaQuestionBank ||= []).push(...[{"id":"mss-labs-anatomy-04-quiz-1","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Thenar muscles","Abductor pollicis brevis","Flexor pollicis brevis","Hypothenar muscles","Palmar aponeurosis"],"answer":0,"explanation":"Thenar muscles: Thenar eminence = abductor pollicis brevis + flexor pollicis brevis + opponens pollicis → recurrent (thenar) branch of median nerve.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-2","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Thenar muscles","Palmar aponeurosis","Palmaris brevis","Hypothenar muscles","Abductor digiti minimi"],"answer":2,"explanation":"Palmaris brevis: Small subcutaneous muscle over the hypothenar eminence; ulnar nerve (superficial branch). Wrinkles skin, protects ulnar vessels/nerve.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-3","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Palmar aponeurosis","Median nerve","Thenar muscles","Hypothenar muscles","Guyon’s canal"],"answer":4,"explanation":"Guyon’s canal: Ulnar tunnel between pisiform and hook of hamate, superficial to the flexor retinaculum. Contains ulnar nerve + artery.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-4","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Hypothenar muscles","Ulnar Artery","Palmar aponeurosis","Median nerve","Thenar muscles"],"answer":1,"explanation":"Ulnar Artery: Accompanies ulnar nerve through Guyon’s canal; main source of the superficial palmar arch.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-5","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Median nerve","Thenar muscles","Hypothenar muscles","Flexor retinaculum","Palmar aponeurosis"],"answer":3,"explanation":"Flexor retinaculum: Roof of carpal tunnel: scaphoid tubercle + trapezium (lateral) to pisiform + hook of hamate (medial). Median nerve + 9 tendons pass deep to it.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-6","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Flexor pollicis brevis","Thenar muscles","Abductor pollicis brevis","Hypothenar muscles","Palmar aponeurosis"],"answer":0,"explanation":"Flexor pollicis brevis: Flexes thumb at MCP joint; median nerve (recurrent branch; deep head often ulnar).","labImage":true},{"id":"mss-labs-anatomy-04-quiz-7","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Thenar muscles","Palmar aponeurosis","Abductor digiti minimi","Hypothenar muscles","Palmaris brevis"],"answer":2,"explanation":"Abductor digiti minimi: Abducts little finger. Most medial/superficial hypothenar muscle; ulnar nerve (deep branch).","labImage":true},{"id":"mss-labs-anatomy-04-quiz-8","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Palmar aponeurosis","Median nerve","Thenar muscles","Hypothenar muscles","Deep palmar arch"],"answer":4,"explanation":"Deep palmar arch: Mainly radial artery (completed by deep branch of ulnar). Lies deep to flexor tendons at base of metacarpals, proximal to the superficial arch.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-9","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Hypothenar muscles","Oblique head of adductor pollicis","Transverse head of adductor pollicis","1st dorsal interosseous muscle","Thenar muscles"],"answer":1,"explanation":"Oblique head of adductor pollicis: Adductor pollicis, oblique head: from capitate + bases of 2nd–3rd metacarpals. Radial artery passes between the two heads.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-10","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Radial artery","Thenar muscles","Hypothenar muscles","Palmar aponeurosis","Median nerve"],"answer":3,"explanation":"Palmar aponeurosis: Thickened deep fascia of the palm, continuous with the palmaris longus tendon. Fibrosis → Dupuytren’s contracture (ring/little finger).","labImage":true},{"id":"mss-labs-anatomy-04-quiz-11","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Superficial palmar arch","Palmar aponeurosis","Median nerve","Thenar muscles","Hypothenar muscles"],"answer":0,"explanation":"Superficial palmar arch: Mainly ulnar artery (completed by superficial palmar branch of radial). Lies superficial to long flexor tendons, distal to the deep arch.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-12","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Hypothenar muscles","Palmar aponeurosis","Tendons of flexor digitorum profundus","Tendons of flexor digitorum superficialis","Thenar muscles"],"answer":2,"explanation":"Tendons of flexor digitorum profundus: Pass through the FDS split → base of DISTAL phalanx; flex DIP joints. Lateral 2 median (AIN), medial 2 ulnar.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-13","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Thenar muscles","Flexor pollicis brevis","Hypothenar muscles","Palmar aponeurosis","Abductor pollicis brevis"],"answer":4,"explanation":"Abductor pollicis brevis: Abducts thumb. Most superficial thenar muscle; median nerve (recurrent branch).","labImage":true},{"id":"mss-labs-anatomy-04-quiz-14","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Palmar aponeurosis","Opponens digiti minimi","Hypothenar muscles","Palmaris brevis","Thenar muscles"],"answer":1,"explanation":"Opponens digiti minimi: Draws 5th metacarpal forward (opposition). Deepest hypothenar muscle; ulnar nerve (deep branch).","labImage":true},{"id":"mss-labs-anatomy-04-quiz-15","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["3rd Lumbrical","Thenar muscles","Hypothenar muscles","2nd Lumbrical","1st Lumbrical"],"answer":3,"explanation":"2nd Lumbrical: Unipennate; arise from FDP tendons of index/middle; median nerve. Flex MCP, extend IP joints via extensor expansion.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-16","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["4th Lumbrical","1st Lumbrical","2nd Lumbrical","Thenar muscles","Hypothenar muscles"],"answer":0,"explanation":"4th Lumbrical: Bipennate (arise from two adjacent FDP tendons); ulnar nerve (deep branch). Flex MCP, extend IP joints.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-17","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Thenar muscles","Hypothenar muscles","1st dorsal interosseous muscle","Transverse head of adductor pollicis","Oblique head of adductor pollicis"],"answer":2,"explanation":"1st dorsal interosseous muscle: Two heads — radial artery passes between them. Bipennate, abducts index finger; ulnar nerve (deep branch).","labImage":true},{"id":"mss-labs-anatomy-04-quiz-18","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Transverse head of adductor pollicis","Oblique head of adductor pollicis","Thenar muscles","Hypothenar muscles","3rd dorsal interosseous"],"answer":4,"explanation":"3rd dorsal interosseous: Bipennate; ABduct fingers away from middle finger (DAB); ulnar nerve (deep branch). Palmar interossei (PAD) are unipennate.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-19","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Hypothenar muscles","Radial artery","Palmar aponeurosis","Median nerve","Thenar muscles"],"answer":1,"explanation":"Radial artery: Lateral to FCR tendon (pulse) → snuffbox → between 1st dorsal interosseous heads → deep palmar arch.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-20","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Abductor pollicis brevis","Hypothenar muscles","Palmar aponeurosis","Extensor pollicis longus","Thenar muscles"],"answer":3,"explanation":"Extensor pollicis longus: MEDIAL border of snuffbox; extends thumb IP joint; posterior interosseous nerve (radial).","labImage":true},{"id":"mss-labs-anatomy-04-quiz-21","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Abductor pollicis longus","Thenar muscles","Abductor pollicis brevis","Hypothenar muscles","Palmar aponeurosis"],"answer":0,"explanation":"Abductor pollicis longus: Most proximal/lateral of the 3 deep thumb muscles; lateral wall of snuffbox; abducts thumb.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-22","lectureId":"mss-labs-anatomy-04","question":"Identify the structure marked by the pulsing ring.","options":["Hypothenar muscles","Palmar aponeurosis","Extensor pollicis brevis","Thenar muscles","Abductor pollicis brevis"],"answer":2,"explanation":"Extensor pollicis brevis: LATERAL wall of snuffbox (with APL); extends thumb MCP joint.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-23","lectureId":"mss-labs-anatomy-04","question":"Which nerve supplies the marked muscle?","options":["Deep branch of the ulnar nerve","Superficial branch of the radial nerve","Posterior interosseous nerve","Anterior interosseous nerve","Recurrent branch of the median nerve"],"answer":4,"explanation":"Thenar muscles (APB, FPB, opponens pollicis) = recurrent branch of median nerve (LOAF).","labImage":true},{"id":"mss-labs-anatomy-04-quiz-24","lectureId":"mss-labs-anatomy-04","question":"Which nerve supplies the marked muscle?","options":["Axillary nerve","Deep branch of the ulnar nerve","Recurrent branch of the median nerve","Radial nerve","Musculocutaneous nerve"],"answer":1,"explanation":"Hypothenar muscles are supplied by the deep branch of the ulnar nerve.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-25","lectureId":"mss-labs-anatomy-04","question":"The marked muscle is a unipennate lumbrical. Its nerve supply is:","options":["Radial nerve","Both median and ulnar equally","Musculocutaneous nerve","Median nerve","Ulnar nerve (deep branch)"],"answer":3,"explanation":"1st and 2nd lumbricals: unipennate, median nerve. 3rd and 4th: bipennate, ulnar nerve.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-26","lectureId":"mss-labs-anatomy-04","question":"The marked lumbrical is bipennate. Its nerve supply is:","options":["Deep branch of the ulnar nerve","Median nerve","Radial nerve","Anterior interosseous nerve","Superficial branch of the ulnar nerve"],"answer":0,"explanation":"3rd and 4th lumbricals arise from two adjacent FDP tendons (bipennate) and are supplied by the deep ulnar nerve.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-27","lectureId":"mss-labs-anatomy-04","question":"Which statement fits the marked pair of lumbricals?","options":["Unipennate, ulnar nerve","Unipennate, radial nerve","Bipennate, ulnar nerve","Unipennate, median nerve","Bipennate, median nerve"],"answer":2,"explanation":"3rd and 4th lumbricals = bipennate + ulnar. 1st and 2nd = unipennate + median.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-28","lectureId":"mss-labs-anatomy-04","question":"The radial artery passes between the heads of the marked muscle on its way to the deep palmar arch. The muscle is:","options":["1st palmar interosseous","Opponens pollicis","1st lumbrical","Flexor pollicis brevis","1st dorsal interosseous"],"answer":4,"explanation":"Radial artery crosses between the 2 heads of 1st dorsal interosseous, then forms the deep arch.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-29","lectureId":"mss-labs-anatomy-04","question":"The marked muscle adducts the thumb. Weakness gives a positive Froment’s sign. Its nerve is:","options":["Musculocutaneous nerve","Deep branch of the ulnar nerve","Recurrent branch of the median nerve","Posterior interosseous nerve","Anterior interosseous nerve"],"answer":1,"explanation":"Adductor pollicis (transverse head shown) is supplied by the deep ulnar nerve.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-30","lectureId":"mss-labs-anatomy-04","question":"The marked dorsal interosseous is:","options":["Bipennate; adducts the finger","Unipennate; flexes the MCP joint","Bipennate; supplied by the median nerve","Bipennate; abducts the finger (DAB)","Unipennate; adducts the finger (PAD)"],"answer":3,"explanation":"All 4 dorsal interossei are bipennate, ABduct (DAB), ulnar nerve.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-31","lectureId":"mss-labs-anatomy-04","question":"Which tendon forms the medial wall (1 tendon) of the snuffbox?","options":["Extensor pollicis longus","Extensor pollicis brevis","Abductor pollicis longus","Extensor carpi radialis longus","Flexor pollicis longus"],"answer":0,"explanation":"Medial wall = EPL; lateral wall = APL + EPB.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-32","lectureId":"mss-labs-anatomy-04","question":"Which tendons form the lateral wall (2 tendons) of the snuffbox?","options":["ECRL + ECRB","FPL + APB","APL + EPB","EPL + EPB","APL + EPL"],"answer":2,"explanation":"Lateral wall = abductor pollicis longus + extensor pollicis brevis.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-33","lectureId":"mss-labs-anatomy-04","question":"The marked muscle lies deep to abductor pollicis brevis. It is:","options":["Flexor pollicis brevis","Adductor pollicis","Opponens digiti minimi","1st dorsal interosseous","Opponens pollicis"],"answer":4,"explanation":"Opponens pollicis: deep thenar muscle, opposition, recurrent median nerve.","labImage":true},{"id":"mss-labs-anatomy-04-quiz-34","lectureId":"mss-labs-anatomy-04","question":"What passes through the carpal tunnel?","options":["Ulnar nerve + 9 tendons","Median nerve + 9 tendons (4 FDS, 4 FDP, FPL)","Ulnar nerve + ulnar artery","Median nerve + 8 tendons","Median nerve, radial artery + 9 tendons"],"answer":1,"explanation":"Median nerve + 9 flexor tendons. The ulnar nerve/artery go through Guyon’s canal, superficial to the retinaculum.","labImage":false},{"id":"mss-labs-anatomy-04-quiz-35","lectureId":"mss-labs-anatomy-04","question":"Guyon’s canal lies between which bony points?","options":["Capitate and lunate","Trapezium and hook of hamate","Pisiform and scaphoid","Pisiform and hook of hamate","Scaphoid tubercle and trapezium"],"answer":3,"explanation":"Pisiform ↔ hook of hamate; contains ulnar nerve + artery.","labImage":false},{"id":"mss-labs-anatomy-04-quiz-36","lectureId":"mss-labs-anatomy-04","question":"The superficial palmar arch is mainly formed by:","options":["Ulnar artery","Radial artery","Anterior interosseous artery","Princeps pollicis artery","Deep branch of ulnar artery"],"answer":0,"explanation":"Superficial arch = ulnar artery (+ superficial palmar branch of radial). Deep arch = radial artery.","labImage":false},{"id":"mss-labs-anatomy-04-quiz-37","lectureId":"mss-labs-anatomy-04","question":"The deep palmar arch is mainly a continuation of:","options":["Common interosseous artery","Superficial palmar branch of radial","Radial artery","Ulnar artery","Brachial artery"],"answer":2,"explanation":"Radial artery → between 1st dorsal interosseous heads → deep palmar arch.","labImage":false},{"id":"mss-labs-anatomy-04-quiz-38","lectureId":"mss-labs-anatomy-04","question":"Correct order of structures in the cubital fossa, medial → lateral:","options":["Radial nerve, biceps tendon, brachial artery, median nerve","Brachial artery, median nerve, biceps tendon, radial nerve","Median nerve, biceps tendon, brachial artery, radial nerve","Ulnar nerve, brachial artery, biceps tendon, radial nerve","Median nerve, brachial artery, biceps tendon, radial nerve"],"answer":4,"explanation":"Median n. → brachial a. → biceps tendon → radial n.","labImage":false},{"id":"mss-labs-anatomy-04-quiz-39","lectureId":"mss-labs-anatomy-04","question":"Where is the radial pulse best felt at the distal forearm?","options":["Deep to pronator quadratus","Lateral to the FCR tendon, medial to brachioradialis tendon","Medial to the FCR tendon","Lateral to brachioradialis tendon","Between FDS and FDP tendons"],"answer":1,"explanation":"Radial artery lies between brachioradialis tendon (lateral) and FCR tendon (medial).","labImage":false},{"id":"mss-labs-anatomy-04-quiz-40","lectureId":"mss-labs-anatomy-04","question":"Which of these is a SUPERFICIAL posterior forearm muscle (not one of the deep muscles)?","options":["Extensor pollicis brevis","Extensor pollicis longus","Supinator","Extensor carpi radialis brevis","Abductor pollicis longus"],"answer":3,"explanation":"Deep posterior group: supinator + the 3 to the thumb (APL, EPB, EPL). ECRB is superficial.","labImage":false},{"id":"mss-labs-anatomy-04-quiz-41","lectureId":"mss-labs-anatomy-04","question":"The only long flexor tendon to the thumb is:","options":["Flexor pollicis longus","Flexor digitorum profundus","Flexor pollicis brevis","Flexor digitorum superficialis","Abductor pollicis longus"],"answer":0,"explanation":"FPL, from the deep anterior forearm layer. FDP → base of distal phalanx; FDS → base of middle phalanx.","labImage":false},{"id":"mss-labs-anatomy-04-quiz-42","lectureId":"mss-labs-anatomy-04","question":"In the anterior forearm, flexor digitorum superficialis belongs to which layer?","options":["Lateral compartment","Posterior compartment","Intermediate","Superficial","Deep"],"answer":2,"explanation":"Superficial: pronator teres, FCR, palmaris longus, FCU. Intermediate: FDS. Deep: FDP, FPL, pronator quadratus.","labImage":false},{"id":"mss-labs-anatomy-04-quiz-43","lectureId":"mss-labs-anatomy-04","question":"Which muscle floors the cubital fossa and belongs to the deep posterior forearm group?","options":["Pronator teres","Brachioradialis","Anconeus","Flexor carpi radialis","Supinator"],"answer":4,"explanation":"Supinator forms the floor of the cubital fossa (deep posterior group).","labImage":false},{"id":"mss-labs-anatomy-05-quiz-1","lectureId":"mss-labs-anatomy-05","question":"Which nerve supplies the muscle marked here?","options":["Femoral nerve","Obturator nerve","Superior gluteal nerve","Inferior gluteal nerve"],"answer":2,"explanation":"Gluteus medius and minimus are supplied by the superior gluteal nerve.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-2","lectureId":"mss-labs-anatomy-05","question":"Which nerve supplies the marked muscle?","options":["Superior gluteal nerve","Nerve to quadratus femoris","Sciatic nerve","Inferior gluteal nerve"],"answer":3,"explanation":"Gluteus maximus is supplied by the inferior gluteal nerve.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-3","lectureId":"mss-labs-anatomy-05","question":"Injury to the nerve supplying gluteus medius and minimus gives which gait finding?","options":["Pelvic drop while walking","Foot drop","Loss of knee extension","Inability to adduct the thigh"],"answer":0,"explanation":"These muscles stabilise the pelvis during walking; their loss causes pelvic drop (Trendelenburg sign).","labImage":false},{"id":"mss-labs-anatomy-05-quiz-4","lectureId":"mss-labs-anatomy-05","question":"Injury to the marked tract is associated with which symptom?","options":["Hip dislocation","Knee pain","Shoulder pain","Foot drop"],"answer":1,"explanation":"The note on this slide links iliotibial tract injury with knee pain.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-5","lectureId":"mss-labs-anatomy-05","question":"The marked muscle and gluteus maximus both continue into which structure?","options":["Inguinal ligament","Patellar ligament","Iliotibial tract","Sacrotuberous ligament"],"answer":2,"explanation":"Tensor fasciae latae and gluteus maximus feed into the iliotibial tract.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-6","lectureId":"mss-labs-anatomy-05","question":"How do the superior gluteal nerve and vessels relate to the marked muscle?","options":["They pass below it","They pierce it","They pass through the lesser sciatic foramen","They pass above it"],"answer":3,"explanation":"Superior gluteal nerve and vessels pass above piriformis; inferior structures pass below.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-7","lectureId":"mss-labs-anatomy-05","question":"The tendon of the marked muscle leaves the pelvis through which opening?","options":["Lesser sciatic foramen","Greater sciatic foramen above piriformis","Obturator canal","Femoral ring"],"answer":0,"explanation":"Obturator internus turns around the ischium and exits through the lesser sciatic foramen.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-8","lectureId":"mss-labs-anatomy-05","question":"Which group passes through the lesser sciatic foramen with the obturator internus tendon?","options":["Inferior gluteal nerve and vessels","Nerve to obturator internus, internal pudendal vessels, pudendal nerve","Superior gluteal nerve and vessels","Sciatic nerve and posterior cutaneous nerve of thigh"],"answer":1,"explanation":"Pins 1, 2, 3 on this specimen all pass through the lesser sciatic foramen.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-9","lectureId":"mss-labs-anatomy-05","question":"Which ligament forms the inferior boundary of the lesser sciatic foramen?","options":["Inguinal ligament","Iliofemoral ligament","Sacrotuberous ligament","Sacrospinous ligament"],"answer":2,"explanation":"Sacrospinous ligament and ischial spine form the upper border; sacrotuberous forms the lower border.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-10","lectureId":"mss-labs-anatomy-05","question":"The marked muscle belongs to which group?","options":["Hamstrings","Adductors","Iliopsoas","Quadriceps femoris"],"answer":3,"explanation":"Rectus femoris, vastus medialis, intermedius and lateralis make up quadriceps femoris.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-11","lectureId":"mss-labs-anatomy-05","question":"Which of these is NOT part of quadriceps femoris?","options":["Sartorius","Rectus femoris","Vastus intermedius","Vastus medialis"],"answer":0,"explanation":"Sartorius is a separate strap muscle, not a quadriceps head.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-12","lectureId":"mss-labs-anatomy-05","question":"The marked muscle runs between which two bony lines?","options":["Pubic symphysis and tibial tuberosity","Pectineal line of hip bone and pectineal line of femur","Iliac crest and greater trochanter","Ischial tuberosity and linea aspera"],"answer":1,"explanation":"Pectineus runs from the pectineal line of the hip bone to the pectineal line of the femur.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-13","lectureId":"mss-labs-anatomy-05","question":"Which muscle lies directly beneath the marked adductor longus?","options":["Gracilis","Sartorius","Adductor brevis","Adductor magnus"],"answer":2,"explanation":"Adductor brevis lies deep to adductor longus (note on the anterior thigh slide).","labImage":true},{"id":"mss-labs-anatomy-05-quiz-14","lectureId":"mss-labs-anatomy-05","question":"Which muscle’s medial border forms the lateral boundary of the femoral triangle?","options":["Adductor longus","Pectineus","Rectus femoris","Sartorius"],"answer":3,"explanation":"Lateral boundary: medial border of sartorius.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-15","lectureId":"mss-labs-anatomy-05","question":"Which muscle’s medial border forms the medial boundary of the femoral triangle?","options":["Adductor longus","Sartorius","Gracilis","Pectineus"],"answer":0,"explanation":"Medial boundary: medial border of adductor longus.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-16","lectureId":"mss-labs-anatomy-05","question":"The floor of the femoral triangle from lateral to medial is made by:","options":["Iliopsoas, sartorius, gracilis","Iliopsoas, pectineus, adductor longus","Pectineus, iliopsoas, adductor longus","Adductor longus, pectineus, sartorius"],"answer":1,"explanation":"Floor (gutter-shaped), lateral to medial: iliopsoas, pectineus, adductor longus.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-17","lectureId":"mss-labs-anatomy-05","question":"How do the femoral artery and vein reach the posterior thigh from the adductor canal?","options":["Through the greater sciatic foramen","Behind the inguinal ligament","Through the adductor hiatus","Through the obturator canal"],"answer":2,"explanation":"They pass through the adductor hiatus into the posterior compartment.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-18","lectureId":"mss-labs-anatomy-05","question":"The marked spine lies between which two notches?","options":["Lesser sciatic notch above, greater sciatic notch below","Acetabular notch and greater sciatic notch","Two notches of the iliac crest","Greater sciatic notch above, lesser sciatic notch below"],"answer":3,"explanation":"Ischial spine separates the greater (above) from the lesser (below) sciatic notch.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-19","lectureId":"mss-labs-anatomy-05","question":"The marked foramen is bounded by which bones?","options":["Ischium and pubis","Ilium and ischium","Ilium and pubis","Sacrum and ilium"],"answer":0,"explanation":"The largest foramen in the skeleton is surrounded by ischium and pubis.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-20","lectureId":"mss-labs-anatomy-05","question":"The marked line plus the pectineal line forms which landmark?","options":["Pubic arch","Pelvic brim","Pelvic outlet","Linea terminalis of the sacrum only"],"answer":1,"explanation":"Arcuate line plus pectineal line = pelvic brim, separating false from true pelvis.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-21","lectureId":"mss-labs-anatomy-05","question":"Which ligament attaches to the marked line?","options":["Sacrotuberous ligament","Patellar ligament","Iliofemoral ligament","Ligament of the head of femur"],"answer":2,"explanation":"The iliofemoral ligament attaches along the intertrochanteric line.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-22","lectureId":"mss-labs-anatomy-05","question":"Which muscle attaches to the marked tuberosity?","options":["Gluteus medius","Iliopsoas","Piriformis","Gluteus maximus"],"answer":3,"explanation":"Gluteus maximus attaches to the gluteal tuberosity, the lateral margin of the linea aspera.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-23","lectureId":"mss-labs-anatomy-05","question":"Which ligament attaches to the lateral surface of the medial condyle wall of the marked fossa?","options":["Posterior cruciate ligament","Anterior cruciate ligament","Patellar ligament","Medial collateral ligament"],"answer":0,"explanation":"PCL: lateral surface of the medial condyle. ACL: medial surface of the lateral condyle.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-24","lectureId":"mss-labs-anatomy-05","question":"Which muscle attaches to the marked oblique line?","options":["Popliteus","Soleus","Gastrocnemius","Tibialis anterior"],"answer":1,"explanation":"The soleal line gives attachment to soleus.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-25","lectureId":"mss-labs-anatomy-05","question":"With which bone does the marked bone articulate posteriorly?","options":["Navicular","Lateral cuneiform","Calcaneus","Talus"],"answer":2,"explanation":"The cuboid articulates posteriorly with the calcaneus.","labImage":true},{"id":"mss-labs-anatomy-05-quiz-26","lectureId":"mss-labs-anatomy-05","question":"The groove beneath the marked projection carries which tendon?","options":["Tibialis posterior","Fibularis longus","Extensor hallucis longus","Flexor hallucis longus"],"answer":3,"explanation":"The tendon of flexor hallucis longus runs in the groove below the sustentaculum tali.","labImage":true},{"id":"mss-labs-anatomy-06-quiz-1","lectureId":"mss-labs-anatomy-06","question":"The ringed muscle is supplied by which nerve component?","options":["Obturator nerve","Inferior gluteal nerve","Tibial part of sciatic","Common fibular part of sciatic"],"answer":3,"explanation":"Short head of biceps femoris: the only posterior thigh muscle supplied by the common fibular part.","labImage":false},{"id":"mss-labs-anatomy-06-quiz-2","lectureId":"mss-labs-anatomy-06","question":"The ringed muscle is supplied by:","options":["Common fibular nerve","Femoral nerve","Superior gluteal nerve","Tibial part of sciatic"],"answer":3,"explanation":"Semimembranosus (like semitendinosus and the long head of biceps) uses the tibial portion.","labImage":false},{"id":"mss-labs-anatomy-06-quiz-3","lectureId":"mss-labs-anatomy-06","question":"The ringed point is where the sciatic nerve divides. Into which nerves?","options":["Tibial and saphenous","Femoral and obturator","Tibial and common fibular","Sural and superficial fibular"],"answer":2,"explanation":"Tibial (medial) and common fibular (lateral).","labImage":true},{"id":"mss-labs-anatomy-06-quiz-4","lectureId":"mss-labs-anatomy-06","question":"Femoral vessels pass through a gap beside the ringed muscle and become popliteal vessels. The gap is the:","options":["Adductor hiatus","Femoral canal","Obturator canal","Greater sciatic foramen"],"answer":0,"explanation":"Adductor hiatus in adductor magnus.","labImage":false},{"id":"mss-labs-anatomy-06-quiz-5","lectureId":"mss-labs-anatomy-06","question":"The ringed muscle with its partner forms which border of the popliteal fossa?","options":["Inferomedial","Inferolateral","Superolateral","Superomedial"],"answer":3,"explanation":"Semitendinosus + semimembranosus = superomedial border.","labImage":false},{"id":"mss-labs-anatomy-06-quiz-6","lectureId":"mss-labs-anatomy-06","question":"The ringed head, with plantaris, forms which border of the popliteal fossa?","options":["Inferomedial","Inferolateral","Superolateral","Superomedial"],"answer":1,"explanation":"Lateral head of gastrocnemius + plantaris = inferolateral.","labImage":true},{"id":"mss-labs-anatomy-06-quiz-7","lectureId":"mss-labs-anatomy-06","question":"Nerve and artery of the compartment of the ringed muscle:","options":["Tibial n.; posterior tibial a.","Superficial fibular n.; fibular a.","Deep fibular n.; anterior tibial a.","Sural n.; popliteal a."],"answer":2,"explanation":"Anterior compartment: deep fibular nerve, anterior tibial artery.","labImage":true},{"id":"mss-labs-anatomy-06-quiz-8","lectureId":"mss-labs-anatomy-06","question":"Nerve and artery of the compartment of the ringed muscle:","options":["Femoral n.; popliteal a.","Superficial fibular n.; fibular a.","Deep fibular n.; anterior tibial a.","Tibial n.; posterior tibial a."],"answer":1,"explanation":"Lateral compartment; fibular a. branches from posterior tibial.","labImage":true},{"id":"mss-labs-anatomy-06-quiz-9","lectureId":"mss-labs-anatomy-06","question":"The ringed deep muscle is supplied by:","options":["Superficial fibular n.","Saphenous n. (fibular a. supplies it)","Deep fibular n.","Tibial n. (posterior tibial a. supplies it)"],"answer":3,"explanation":"Posterior compartment: tibial nerve, posterior tibial artery.","labImage":true},{"id":"mss-labs-anatomy-06-quiz-10","lectureId":"mss-labs-anatomy-06","question":"Which structure is the most lateral one passing under the extensor retinacula (Tom Has Very Nice Dog P)?","options":["Extensor digitorum longus","Deep fibular nerve","Fibularis tertius","Tibialis anterior tendon"],"answer":2,"explanation":"P = peroneus (fibularis) tertius.","labImage":true},{"id":"mss-labs-anatomy-06-quiz-11","lectureId":"mss-labs-anatomy-06","question":"Behind the medial malleolus, which nerve lies between the posterior tibial vessels and the FHL tendon?","options":["Tibial nerve","Saphenous nerve","Sural nerve","Deep fibular nerve"],"answer":0,"explanation":"Tom Does Very Nice Hat: Nice = nerve.","labImage":true},{"id":"mss-labs-anatomy-06-quiz-12","lectureId":"mss-labs-anatomy-06","question":"Which is the most medial tendon behind the medial malleolus?","options":["Tibialis anterior","FHL","Tibialis posterior","FDL"],"answer":2,"explanation":"Tom = tibialis posterior.","labImage":true},{"id":"mss-labs-anatomy-06-quiz-13","lectureId":"mss-labs-anatomy-06","question":"The ringed tendon belongs to a muscle in which compartment, supplied by which nerve?","options":["Posterior; tibial nerve","Lateral; deep fibular nerve","Lateral; superficial fibular nerve","Anterior; deep fibular nerve"],"answer":2,"explanation":"Fibularis longus: lateral compartment, superficial fibular nerve; posterior/lateral under the fibular retinacula.","labImage":true},{"id":"mss-labs-anatomy-06-quiz-14","lectureId":"mss-labs-anatomy-06","question":"The ringed muscle is in sole layer 1. Which set forms the whole layer?","options":["FHB, adductor hallucis, flexor digiti minimi brevis","Abductor hallucis, FDB, abductor digiti minimi","Interossei, adductor hallucis, FDB","Lumbricals, quadratus plantae, FDB"],"answer":1,"explanation":"Layer 1 has three muscles.","labImage":true},{"id":"mss-labs-anatomy-06-quiz-15","lectureId":"mss-labs-anatomy-06","question":"The ringed muscle is in layer 2 together with:","options":["Lumbricals, FDL and FHL tendons","Interossei and fibularis longus tendon","FHB and adductor hallucis","Abductor hallucis and FDB"],"answer":0,"explanation":"Layer 2: lumbricals + quadratus plantae + FDL/FHL tendons.","labImage":true},{"id":"mss-labs-anatomy-06-quiz-16","lectureId":"mss-labs-anatomy-06","question":"The ringed muscle is in layer 3 together with:","options":["Plantar interossei only","Lumbricals and quadratus plantae","Adductor hallucis, flexor digiti minimi brevis","Abductor digiti minimi, FDB, EDB"],"answer":2,"explanation":"Layer 3: FHB + flexor digiti minimi brevis + adductor hallucis.","labImage":true},{"id":"mss-labs-anatomy-06-quiz-17","lectureId":"mss-labs-anatomy-06","question":"The ringed muscle is in layer 4, which consists of:","options":["FHB and abductor hallucis","EDB, EHB and quadratus plantae","3 plantar + 4 dorsal interossei and two tendons","Lumbricals and FDL tendon"],"answer":2,"explanation":"Interossei plus fibularis longus and tibialis posterior tendons.","labImage":true},{"id":"mss-labs-anatomy-06-quiz-18","lectureId":"mss-labs-anatomy-06","question":"The ringed artery continues on the dorsum as the:","options":["Fibular artery","Medial plantar artery","Dorsalis pedis artery","Lateral plantar artery"],"answer":2,"explanation":"Anterior tibial a. becomes dorsalis pedis (pulse).","labImage":true},{"id":"mss-labs-anatomy-06-quiz-19","lectureId":"mss-labs-anatomy-06","question":"The ringed nerve arises from:","options":["Deep fibular nerve","Tibial nerve","Sural nerve","Saphenous nerve"],"answer":1,"explanation":"Tibial nerve divides into medial and lateral plantar nerves.","labImage":true},{"id":"mss-labs-anatomy-06-quiz-20","lectureId":"mss-labs-anatomy-06","question":"The ringed muscle everts the foot at the subtalar joint, together with:","options":["Extensor hallucis longus only","Two tibialis muscles","Gastrocnemius and soleus","The other two fibularis muscles"],"answer":3,"explanation":"Eversion: 3 fibularis; inversion: 2 tibialis.","labImage":true},{"id":"mss-labs-anatomy-06-quiz-21","lectureId":"mss-labs-anatomy-06","question":"Which pair makes up the intrinsic muscles of the dorsum of the foot?","options":["Abductor hallucis and FDB","Quadratus plantae and FHB","Lumbricals and interossei","EHB and EDB"],"answer":3,"explanation":"EDB + EHB.","labImage":true},{"id":"mss-labs-pathology-02-quiz-1","lectureId":"mss-labs-pathology-02","question":"Linear red scratch marks on the shoulder, self-inflicted. The lesion term is:","options":["Excoriation","Lichenification","Macule","Pustule","Plaque"],"answer":0,"explanation":"Excoriation = scratch erosions (self-inflicted).","labImage":true},{"id":"mss-labs-pathology-02-quiz-2","lectureId":"mss-labs-pathology-02","question":"Thickened skin with prominent skin markings from a chronic condition:","options":["Nodule","Pustule","Lichenification","Excoriation","Macule"],"answer":2,"explanation":"Chronic rubbing → skin thickening and accentuated markings = lichenification.","labImage":true},{"id":"mss-labs-pathology-02-quiz-3","lectureId":"mss-labs-pathology-02","question":"A flat, discolored spot ≤ 5 mm is a:","options":["Nodule","Plaque","Pustule","Excoriation","Macule"],"answer":4,"explanation":"Macule: flat, discolored, ≤ 5 mm. Larger than 5 mm = patch.","labImage":true},{"id":"mss-labs-pathology-02-quiz-4","lectureId":"mss-labs-pathology-02","question":"An elevated lesion > 5 mm on the nose:","options":["Excoriation","Nodule","Macule","Pustule","Lichenification"],"answer":1,"explanation":"Nodule = elevated, > 5 mm.","labImage":true},{"id":"mss-labs-pathology-02-quiz-5","lectureId":"mss-labs-pathology-02","question":"The circled fluid-filled spaces between keratinocytes show:","options":["Parakeratosis","Dyskeratosis","Papillomatosis","Spongiosis","Acanthosis"],"answer":3,"explanation":"Spongiosis = epidermal (intercellular) edema with prominent intercellular bridges.","labImage":true},{"id":"mss-labs-pathology-02-quiz-6","lectureId":"mss-labs-pathology-02","question":"Nuclei are retained within the stratum corneum. This is:","options":["Parakeratosis","Hyperkeratosis","Acanthosis","Spongiosis","Dyskeratosis"],"answer":0,"explanation":"Parakeratosis = nuclear retention in the stratum corneum.","labImage":true},{"id":"mss-labs-pathology-02-quiz-7","lectureId":"mss-labs-pathology-02","question":"Epidermal hyperplasia (thickened living epidermis) is called:","options":["Parakeratosis","Dyskeratosis","Acanthosis","Hyperkeratosis","Spongiosis"],"answer":2,"explanation":"Acanthosis = epidermal hyperplasia; hyperkeratosis refers to the stratum corneum.","labImage":true},{"id":"mss-labs-pathology-02-quiz-8","lectureId":"mss-labs-pathology-02","question":"Black arrows: premature keratinization below the stratum granulosum. Term?","options":["Parakeratosis","Spongiosis","Acanthosis","Papillomatosis","Dyskeratosis"],"answer":4,"explanation":"Dyskeratosis occurs in rapid cell turnover and dysplasia.","labImage":true},{"id":"mss-labs-pathology-02-quiz-9","lectureId":"mss-labs-pathology-02","question":"A 66-year-old woman has a 2-month enlarging nodule on her left ear. Biopsy shows dermal nests resembling epidermal squamous cells. Diagnosis?","options":["Lipoma","Squamous cell carcinoma","Basal cell carcinoma","Melanoma","Psoriasis"],"answer":1,"explanation":"Old patient + sun-exposed ear + nests resembling squamous cells = SCC (poor prognosis site).","labImage":true},{"id":"mss-labs-pathology-02-quiz-10","lectureId":"mss-labs-pathology-02","question":"The pink concentric whorls inside the tumor nests are:","options":["Osteoid","Parakeratotic scale","Melanin pigment","Keratin","Lipoblasts"],"answer":3,"explanation":"Keratin (pearls) is typical of well-differentiated SCC.","labImage":true},{"id":"mss-labs-pathology-02-quiz-11","lectureId":"mss-labs-pathology-02","question":"Which lesion, caused by sun exposure with dysplasia in the lower epidermis, is the precursor of SCC?","options":["Actinic keratosis","Psoriasis","Lipoma","Osteochondroma","Lichenification"],"answer":0,"explanation":"Actinic keratosis → SCC in situ → SCC after more mutations and breaching the basement membrane. Looks flat, red, rough (sandpaper-like).","labImage":false},{"id":"mss-labs-pathology-02-quiz-12","lectureId":"mss-labs-pathology-02","question":"A 70-year-old retired farm worker has a facial nodule covered by small telangiectatic vessels. Diagnosis?","options":["Psoriasis","Actinic lichenification","Basal cell carcinoma","Squamous cell carcinoma","Melanoma"],"answer":2,"explanation":"Old, sun exposure, face, telangiectasia → BCC.","labImage":true},{"id":"mss-labs-pathology-02-quiz-13","lectureId":"mss-labs-pathology-02","question":"Nests whose outermost cells align perpendicular to the stroma, with a surrounding gap:","options":["Squamous cell carcinoma","Invasive melanoma","Ewing sarcoma","Liposarcoma","Basal cell carcinoma"],"answer":4,"explanation":"Peripheral palisading + clefting artifact = BCC.","labImage":true},{"id":"mss-labs-pathology-02-quiz-14","lectureId":"mss-labs-pathology-02","question":"Blue-gray elastic/collagen fibers in the dermis, caused by sunlight:","options":["Lipoblasts","Solar elastosis","Keratin pearls","Spongiosis","Osteoid"],"answer":1,"explanation":"Solar elastosis (dermis) goes with actinic keratoses (epidermis) as solar damage.","labImage":true},{"id":"mss-labs-pathology-02-quiz-15","lectureId":"mss-labs-pathology-02","question":"A 56-year-old man’s ‘mole’ is 1 × 1.2 cm, larger than 2 months ago, with irregular borders/pigmentation. Diagnosis?","options":["Seborrheic keratosis","Psoriasis","Squamous cell carcinoma","Melanoma","Basal cell carcinoma"],"answer":3,"explanation":"Enlarging mole, irregular border, color variation (black/gray/red) = melanoma.","labImage":true},{"id":"mss-labs-pathology-02-quiz-16","lectureId":"mss-labs-pathology-02","question":"Dermal large cells, ↑ N/C ratio, binucleation, prominent nucleoli and brown pigment:","options":["Invasive melanoma","Basal cell carcinoma","Squamous cell carcinoma","Psoriasis","Liposarcoma"],"answer":0,"explanation":"Pigment is a strong clue; melanocytes in the dermis are in an abnormal location.","labImage":true},{"id":"mss-labs-pathology-02-quiz-17","lectureId":"mss-labs-pathology-02","question":"A 25-year-old woman has well-demarcated erythematous plaques with silvery-white scales on the hand and back of the neck:","options":["Lichenification","Pustular folliculitis","Psoriasis","Basal cell carcinoma","Actinic keratosis"],"answer":2,"explanation":"Classic psoriasis plaques.","labImage":true},{"id":"mss-labs-pathology-02-quiz-18","lectureId":"mss-labs-pathology-02","question":"Which set describes this ‘test tubes in a rack’ histology?","options":["Spongiosis with fluid-filled spaces","Peripheral palisading with clefts","Keratin pearls in dermal nests","Lipoblasts with scalloped nuclei","Parakeratosis, regular acanthosis, thin suprapapillary plates, thin granular layer"],"answer":4,"explanation":"Psoriasis: hyperkeratosis + parakeratosis, regular acanthosis, thin suprapapillary plates, ↓ granular layer, neutrophils.","labImage":true},{"id":"mss-labs-pathology-02-quiz-19","lectureId":"mss-labs-pathology-02","question":"Tortuous papillary dermal vessels under thin suprapapillary plates explain which sign?","options":["Koplik spots","Auspitz sign","Nikolsky sign","Darier sign","Pastia lines"],"answer":1,"explanation":"Auspitz sign (pinpoint bleeding on scale removal) in psoriasis.","labImage":true},{"id":"mss-labs-pathology-02-quiz-20","lectureId":"mss-labs-pathology-02","question":"A 25-year-old has knee pain; a distal femoral metaphyseal lesion has a blue-gray cartilage cap over bone and marrow. Diagnosis?","options":["Chondrosarcoma","Ewing sarcoma","Metastatic carcinoma","Osteochondroma","Osteosarcoma"],"answer":3,"explanation":"Osteochondroma = bone + cartilage, benign.","labImage":true},{"id":"mss-labs-pathology-02-quiz-21","lectureId":"mss-labs-pathology-02","question":"Multiple osteochondromas indicate:","options":["Multiple hereditary exostoses syndrome","Paget disease of bone","Fibrous dysplasia","Osteogenesis imperfecta","Ewing sarcoma"],"answer":0,"explanation":"Multiple osteochondromas = multiple hereditary exostoses syndrome.","labImage":false},{"id":"mss-labs-pathology-02-quiz-22","lectureId":"mss-labs-pathology-02","question":"A 17-year-old boy has knee pain and a lytic + sclerotic distal femur mass with infiltrative margins and reactive subperiosteal bone. Atypical cells make new bone. Diagnosis?","options":["Osteochondroma","Metastatic carcinoma","Osteosarcoma","Ewing sarcoma","Chondrosarcoma"],"answer":2,"explanation":"Large lesion, infiltrative margin, subperiosteal reaction = malignancy; atypical cells + new bone = osteosarcoma.","labImage":true},{"id":"mss-labs-pathology-02-quiz-23","lectureId":"mss-labs-pathology-02","question":"A 75-year-old man has 4 months of dull constant back pain. The vertebral column shows multiple lesions. Diagnosis?","options":["Paget’s disease of bone","Osteosarcoma","Ewing’s sarcoma","Chondrosarcoma","Metastatic carcinoma"],"answer":4,"explanation":"Multiple vertebral lesions in the elderly = metastasis; search for the primary.","labImage":true},{"id":"mss-labs-pathology-02-quiz-24","lectureId":"mss-labs-pathology-02","question":"A 51-year-old man has 5 months of right hip pain and a right ischial mass: bulky, destructive, with blue-gray material. Diagnosis?","options":["Lipoma","Chondrosarcoma","Osteochondroma","Osteosarcoma","Ewing sarcoma"],"answer":1,"explanation":"Blue/gray = cartilage; bulky destructive mass extending to soft tissue = chondrosarcoma.","labImage":true},{"id":"mss-labs-pathology-02-quiz-25","lectureId":"mss-labs-pathology-02","question":"Atypical cells with cartilage in the background:","options":["Ewing sarcoma","Liposarcoma","Melanoma","Chondrosarcoma","Osteosarcoma"],"answer":3,"explanation":"Atypical cellular lesion + cartilage matrix = chondrosarcoma.","labImage":true},{"id":"mss-labs-pathology-02-quiz-26","lectureId":"mss-labs-pathology-02","question":"An 11-year-old boy has 3 months of leg pain, temperature 37.6 °C, a tibial diaphyseal mass with cortical destruction. Histology shows sheets of round blue cells:","options":["Ewing sarcoma","Osteosarcoma","Chondrosarcoma","Osteochondroma","Lipoma"],"answer":0,"explanation":"Young, diaphysis, fever/constitutional signs, round blue cells = Ewing sarcoma.","labImage":true},{"id":"mss-labs-pathology-02-quiz-27","lectureId":"mss-labs-pathology-02","question":"Molecular signature of Ewing sarcoma:","options":["t(14;18)","t(15;17)","t(11;22)","t(9;22)","t(8;14)"],"answer":2,"explanation":"Ewing sarcoma: t(11;22).","labImage":false},{"id":"mss-labs-pathology-02-quiz-28","lectureId":"mss-labs-pathology-02","question":"Young patient, malignant bone tumor. Which feature favors osteosarcoma rather than Ewing sarcoma?","options":["Fleshy mass with fever","Diaphyseal location with warm tender swelling","Round blue cells","t(11;22)","Sclerotic lesion in the metaphysis"],"answer":4,"explanation":"Osteosarcoma: sclerotic + metaphysis. Ewing: fleshy, tender/warm/swollen, fever, diaphysis.","labImage":false},{"id":"mss-labs-pathology-02-quiz-29","lectureId":"mss-labs-pathology-02","question":"A superficial soft-tissue mass on a 40-year-old man’s arm: yellow, well encapsulated adipocytes. Diagnosis?","options":["Melanoma","Lipoma","Liposarcoma","Osteochondroma","Chondrosarcoma"],"answer":1,"explanation":"Superficial, encapsulated mature fat = lipoma (benign).","labImage":true},{"id":"mss-labs-pathology-02-quiz-30","lectureId":"mss-labs-pathology-02","question":"An enlarging retroperitoneal mass in a 60-year-old man. Circled cells have vacuolated cytoplasm and scalloped hyperchromatic nuclei. Diagnosis?","options":["Chondrosarcoma","Osteosarcoma","Ewing sarcoma","Liposarcoma","Lipoma"],"answer":3,"explanation":"Deep soft tissue + lipoblasts = liposarcoma.","labImage":true},{"id":"mss-labs-pathology-02-quiz-31","lectureId":"mss-labs-pathology-02","question":"The cell that helps diagnose liposarcoma is the:","options":["Lipoblast","Reed-Sternberg cell","Melanophage","Osteoblast","Keratin pearl"],"answer":0,"explanation":"Lipoblast: adipocyte with central/indented or peripheral hyperchromatic nucleus (signet-ring).","labImage":true}]);
